package ca

import (
	"crypto"
	"crypto/tls"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"fmt"
	"os"

	pkcs12 "software.sslmate.com/src/go-pkcs12"
)

// ImportP12 installs a PKCS#12 bundle (certificate + private key) as the
// runtime's root CA. It supports legacy RC2-encrypted bundles such as the one
// generated by Surge.
func (a *Authority) ImportP12(path, passphrase string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read p12: %w", err)
	}
	signer, cert, _, err := decodeP12(raw, passphrase)
	if err != nil {
		return err
	}
	return a.install(cert, signer)
}

// ImportP12Base64 is ImportP12 for a base64-encoded PKCS#12 bundle.
func (a *Authority) ImportP12Base64(encoded, passphrase string) error {
	raw, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		return fmt.Errorf("decode base64 p12: %w", err)
	}
	signer, cert, _, err := decodeP12(raw, passphrase)
	if err != nil {
		return err
	}
	return a.install(cert, signer)
}

func decodeP12(raw []byte, passphrase string) (crypto.Signer, *x509.Certificate, []*x509.Certificate, error) {
	key, cert, cas, err := pkcs12.DecodeChain(raw, passphrase)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("decode p12 (wrong passphrase or unsupported format): %w", err)
	}
	if cert == nil {
		return nil, nil, nil, fmt.Errorf("p12 contains no certificate")
	}
	if !cert.IsCA {
		return nil, nil, nil, fmt.Errorf("p12 certificate %q is not a CA certificate", cert.Subject.CommonName)
	}
	signer, ok := key.(crypto.Signer)
	if !ok {
		return nil, nil, nil, fmt.Errorf("unsupported private key type %T", key)
	}
	return signer, cert, cas, nil
}

func (a *Authority) install(cert *x509.Certificate, signer crypto.Signer) error {
	certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: cert.Raw})
	keyDER, err := x509.MarshalPKCS8PrivateKey(signer)
	if err != nil {
		return fmt.Errorf("marshal private key: %w", err)
	}
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER})
	if err := os.WriteFile(a.paths.CAKey(), keyPEM, 0o600); err != nil {
		return fmt.Errorf("write ca key: %w", err)
	}
	if err := os.WriteFile(a.paths.CAFile(), certPEM, 0o644); err != nil {
		return fmt.Errorf("write ca cert: %w", err)
	}
	a.mu.Lock()
	a.cert, a.key, a.certPEM = cert, signer, certPEM
	a.leaves = map[string]*tls.Certificate{}
	a.mu.Unlock()
	return nil
}
